      "causa_raiz": "No frame 1643, a coleta de lixo gerou uma pausa de gc_collect_ms de 23.18 ms com cpu_ms de 21.61 ms e 6706563 bytes alocados (gc_bytes). O tempo de coleta (23.18 ms) supera o orçamento total do quadro de 16.7 ms/frame e explica integralmente o pico de processamento no frame. A pilha identifica o método StressTestScene.Update(), onde sucessivas concatenações de string em loop e instanciações de arrays de objetos causam alocações contínuas na heap gerenciada, disparando o Garbage Collector.",
      "codigo_refatorado": "using System;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = true;
        public bool stressCpu = true;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++) new GameObject("Empty_" + i);

            if (overdrawLayers > 0 && overdrawMaterial != null) BuildOverdrawLayers();
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                // Evita alocações desnecessárias a cada quadro
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    var allObjects = GameObject.FindObjectsOfType<GameObject>();
                    GC.KeepAlive(allObjects);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++) SpawnOne();
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.material.color = new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value);
                }
            }
        }
    }
}",
      "explicacao_didatica": "O Garbage Collector (GC, ou coletor de lixo) é um mecanismo automático da Unity que limpa dados da memória que o jogo não está mais usando. Quando criamos objetos temporários repetidamente — como no caso de juntar textos usando o operador '+' dentro de um laço de repetição ou instanciar novos arrays —, essa memória é alocada na memória gerenciada (heap). Quando a memória reservada se esgota, o GC pausa a execução do jogo para realizar a limpeza (medida por gc_collect_ms). Como essa pausa durou 23.18 ms, ela ultrapassou sozinha a meta de 16.7 ms por quadro, gerando um congelamento perceptível na tela (queda de taxa de quadros/engasgo). Para evitar isso, não devemos criar strings e arrays descartáveis a cada atualização de quadro."
    }
  ],
  "dicas_level_design": null
}

